Local Lemma nc_bound : forall csz nf cnt au mu : Z, (32 <= csz -> csz * (nf + cnt) <= au -> au <= mu -> mu + 262144 <= 3758096384 -> 0 <= nf -> 0 <= cnt ->
  32 * (nf + cnt) <= 3758096384)%Z.
Proof. intros. nia. Qed.
